CREATE VIEW IF NOT EXISTS telemetry_serving.provider_activity_summary AS SELECT tenant_id,project_id,provider_entity_urn,fact_type,count() AS event_count,min(occurred_at) AS first_occurred_at,max(occurred_at) AS last_occurred_at FROM telemetry_core.provider_operation_fact GROUP BY tenant_id,project_id,provider_entity_urn,fact_type;
CREATE VIEW IF NOT EXISTS telemetry_serving.task_timeline AS SELECT tenant_id,project_id,task_entity_urn,occurred_at,fact_type,operation_name,payload_json,source_system,source_record_id,fact_id,projected_at FROM telemetry_core.task_lifecycle_fact WHERE task_entity_urn IS NOT NULL;
CREATE VIEW IF NOT EXISTS telemetry_serving.sdar_smpp_execution_topology AS SELECT tenant_id,project_id,relation_id,relation_type,source_entity_urn,target_entity_urn,source_system,target_system,valid_from,valid_to,route_id,attempt_no,confidence_class,evidence_fact_ids FROM telemetry_core.entity_relation_fact WHERE (source_system='sdar' AND target_system='smpp') OR (source_system='smpp' AND target_system='sdar');
CREATE VIEW IF NOT EXISTS telemetry_serving.resource_current_state AS SELECT tenant_id,project_id,resource_entity_urn,argMax(payload_json,occurred_at) AS payload_json,max(occurred_at) AS occurred_at,max(projected_at) AS data_watermark FROM telemetry_core.resource_state_fact WHERE resource_entity_urn IS NOT NULL GROUP BY tenant_id,project_id,resource_entity_urn;
CREATE VIEW IF NOT EXISTS telemetry_serving.provider_current_health AS SELECT tenant_id,project_id,provider_entity_urn,argMax(payload_json,occurred_at) AS payload_json,max(occurred_at) AS occurred_at,max(projected_at) AS data_watermark FROM telemetry_core.resource_health_fact GROUP BY tenant_id,project_id,provider_entity_urn;
CREATE VIEW IF NOT EXISTS telemetry_serving.projection_watermark AS SELECT projection_id,projection_version,max(projected_at) AS data_watermark,count() AS projected_facts FROM telemetry_core.provider_operation_fact GROUP BY projection_id,projection_version;
CREATE VIEW IF NOT EXISTS telemetry_serving.telemetry_data_quality AS SELECT 'record_hash_conflict' AS rule_id,tenant_id,project_id,toString(source_record_id) AS subject_id,received_at AS detected_at,'critical' AS severity FROM telemetry_landing.smpp_provider_ops_conflict_v1 UNION ALL SELECT 'normalization_dead_letter', '' AS tenant_id, '' AS project_id, source_record_id AS subject_id, created_at AS detected_at, 'error' AS severity FROM telemetry_normalized.normalization_dead_letter_v1;
